41	import io.micrometer.core.instrument.MeterRegistry;
42	
43	public abstract class AbstractServer implements AutoCloseable, MetricsProducer, Runnable {
44	
45	  private final ServerContext context;
46	  protected final String applicationName;
47	  private final String hostname;
48	  private final String resourceGroup;
49	  private final ProcessMetrics processMetrics;
50	  protected final long idleReportingPeriodNanos;
51	  private volatile long idlePeriodStartNanos = 0L;
52	
53	  protected AbstractServer(String appName, ConfigOpts opts, String[] args) {
54	    this.applicationName = appName;
55	    opts.parseArgs(appName, args);
56	    var siteConfig = opts.getSiteConfiguration();
57	    this.hostname = siteConfig.get(Property.GENERAL_PROCESS_BIND_ADDRESS);
58	    this.resourceGroup = getResourceGroupPropertyValue(siteConfig);
59	    SecurityUtil.serverLogin(siteConfig);
60	    context = new ServerContext(siteConfig);
61	    Logger log = LoggerFactory.getLogger(getClass());
62	    log.info("Version " + Constants.VERSION);
63	    log.info("Instance " + context.getInstanceID());
64	    context.init(appName);
65	    ClassLoaderUtil.initContextFactory(context.getConfiguration());
66	    TraceUtil.initializeTracer(context.getConfiguration());
67	    if (context.getSaslParams() != null) {
68	      // Server-side "client" check to make sure we're logged in as a user we expect to be
69	      context.enforceKerberosLogin();
70	    }
71	    final LowMemoryDetector lmd = context.getLowMemoryDetector();
72	    ScheduledFuture<?> future = context.getScheduledExecutor().scheduleWithFixedDelay(
73	        () -> lmd.logGCInfo(context.getConfiguration()), 0,
74	        lmd.getIntervalMillis(context.getConfiguration()), TimeUnit.MILLISECONDS);
75	    ThreadPools.watchNonCriticalScheduledTask(future);
76	    processMetrics = new ProcessMetrics(context);
77	    idleReportingPeriodNanos = TimeUnit.MILLISECONDS.toNanos(
78	        context.getConfiguration().getTimeInMillis(Property.GENERAL_IDLE_PROCESS_INTERVAL));
79	  }
80	
81	  protected void idleProcessCheck(Supplier<Boolean> idleCondition) {
82	    boolean idle = idleCondition.get();
83	    if (!idle || idleReportingPeriodNanos == 0) {
84	      idlePeriodStartNanos = 0;
85	    } else if (idlePeriodStartNanos == 0) {
86	      idlePeriodStartNanos = System.nanoTime();
87	    } else if ((System.nanoTime() - idlePeriodStartNanos) > idleReportingPeriodNanos) {
88	      // increment the counter and reset the start of the idle period.
89	      processMetrics.incrementIdleCounter();
90	      idlePeriodStartNanos = 0;
91	    } else {
92	      // idleStartPeriod is non-zero, but we have not hit the idleStopPeriod yet
93	    }
94	  }
95	
96	  protected String getResourceGroupPropertyValue(SiteConfiguration conf) {
97	    return Constants.DEFAULT_RESOURCE_GROUP_NAME;
98	  }
99	
100	  public String getResourceGroup() {
101	    return resourceGroup;
102	  }
103	
104	  /**
105	   * Run this server in a main thread
106	   */
107	  public void runServer() throws Exception {
108	    final AtomicReference<Throwable> err = new AtomicReference<>();
109	    Thread service = new Thread(TraceUtil.wrap(this), applicationName);
110	    service.setUncaughtExceptionHandler((thread, exception) -> err.set(exception));
111	    service.start();
112	    service.join();
113	    Throwable thrown = err.get();
114	    if (thrown != null) {
115	      if (thrown instanceof Error) {
116	        throw (Error) thrown;
117	      }
118	      if (thrown instanceof Exception) {
119	        throw (Exception) thrown;
120	      }
121	      throw new IllegalStateException("Weird throwable type thrown", thrown);
122	    }
123	  }
124	
125	  /**
126	   * Called
127	   */
128	  @Override
129	  public void registerMetrics(MeterRegistry registry) {
130	    // makes mocking subclasses easier
131	    if (processMetrics != null) {
132	      processMetrics.registerMetrics(registry);
133	    }
134	    getContext().setMeterRegistry(registry);
135	  }
136	
137	  public String getHostname() {
138	    return hostname;
139	  }
140	
141	  public ServerContext getContext() {
142	    return context;
143	  }
144	
145	  public AccumuloConfiguration getConfiguration() {
146	    return getContext().getConfiguration();
147	  }
148	
149	  public String getApplicationName() {
150	    return applicationName;
151	  }
152	
153	  @Override
154	  public void close() {}
155	
156	}
