public class FlakyAmpleServerContext extends ServerContext {

  private final Supplier<Ample> ample =
      Suppliers.memoize(() -> TestAmple.create(this, Map.of(DataLevel.METADATA,
          DataLevel.METADATA.metaTable(), DataLevel.USER, DataLevel.USER.metaTable()),
          FlakyInterceptor::new));

  public FlakyAmpleServerContext(SiteConfiguration siteConfig) {
    super(siteConfig);
  }

  @Override
  public Ample getAmple() {
    return ample.get();
  }
}
